{
  "name": "Pfeiffer 真空泵（RS-485 串口）",
  "name_en": "Pfeiffer Vacuum Pump (RS-485 Serial)",
  "manufacturer": "Pfeiffer Vacuum",
  "description": "Pfeiffer 的真空泵或其配套控制单元，可通过 RS-485 串行总线进行通信。该类设备常用于实验室真空系统中，用于接收设备消息并进行运行状态监测与远程通信。",
  "description_en": "A Pfeiffer vacuum pump or associated control unit that communicates over an RS-485 serial link. This type of device is used in laboratory vacuum systems to receive device messages and support operation monitoring and remote communication.",
  "actions": [
    {
      "action_name": "auto-close",
      "description": "关闭与设备的 RS-485 串口通信连接。",
      "description_en": "Close the RS-485 serial communication link to the device."
    },
    {
      "action_name": "auto-nextMessage",
      "description": "读取并解析设备发出的下一条消息。",
      "description_en": "Read and decode the next message sent by the device."
    },
    {
      "action_name": "auto-serialReadNextLine",
      "description": "从串口读取设备返回的下一行原始数据。",
      "description_en": "Read the next raw line returned by the device from the serial interface."
    }
  ],
  "tag_hints": [
    "vacuum pumps",
    "Pfeiffer Vacuum",
    "RS-485 serial communication",
    "vacuum system monitoring",
    "industrial vacuum equipment"
  ]
}

